// QUORMEL 1 – KI gegen KI: zwei unabhängige Lernstände, Auswertung, Vergleich der besten Fahrten.
import {app} from "../state.js";
import {$,mdl,show,toast} from "./dom.js";
import {ACT} from "../core/constants.js";
import {mul} from "../core/rng.js";
import {PRE,cat,rs,setTrack} from "../core/track.js";
import {getQ,keyOf,resetCar,trainStep} from "../core/qlearning.js";
import {setPU} from "./sim.js";
import {drawCar,drawSim} from "../render/sim-view.js";
import {fsOn} from "./race.js";
import {LCTRL,LPAR} from "./lab.js";
import {hd} from "../render/hidpi.js";

// ===== KI gegen KI: zwei unabhängige Q-Learning-Systeme, Kontext wird pro Schritt getauscht =====
export const SUG={a:[.1,.8],g:[.5,.95],e:[.3,1],d:[.98,.995],rg:[20,200],rc:[30,200],rp:[1,6],ri:[0,2]};
export const getC=()=>({Q:app.Q,P:app.P,c:app.c,S:app.S,sn:app.sn,epN:app.epN,ok:app.ok,fail:app.fail,hist:app.hist,best:app.best,rec:app.rec,epRew:app.epRew,sumRew:app.sumRew,sumSteps:app.sumSteps,maxIdx:app.maxIdx,last:app.last,logs:app.logs,recent:app.recent,okSteps:app.okSteps,epLog:app.epLog,fails:app.fails});
export const setC=o=>{({Q:app.Q,P:app.P,c:app.c,S:app.S,sn:app.sn,epN:app.epN,ok:app.ok,fail:app.fail,hist:app.hist,best:app.best,rec:app.rec,epRew:app.epRew,sumRew:app.sumRew,sumSteps:app.sumSteps,maxIdx:app.maxIdx,last:app.last,logs:app.logs,recent:app.recent,okSteps:app.okSteps,epLog:app.epLog,fails:app.fails}=o)};
export function avgMax(){let t=0;app.Q.forEach(q=>t+=Math.max(...q));return app.Q.size?t/app.Q.size:0}
export function koSet(v){["ka","kb"].forEach((id,i)=>{const e=$(id);e.min=app.KP.min;e.max=app.KP.max;e.step=app.KP.st;e.value=v[i];$(id+"v").textContent=v[i]});$("kv").style.display="block"}
export function djBtns(){const m=!app.DU?"":app.DU.done?"done":app.DU.run?"run":"pause";$("jGo").hidden=$("jEnd").hidden=!(m==="run"||m==="pause");$("jGo").textContent=m==="pause"?"Duell fortsetzen":"Duell pausieren";$("jRetry").hidden=$("jBack").hidden=m!=="done";$("jS").parentNode.hidden=m==="done"}
export function duStep(sd){const o=app.DU[sd];if(o.ctx.epN>=app.DU.n)return;setC(o.ctx);const R0=Math.random;Math.random=o.rng;for(let i=0;i<app.DU.spf&&app.epN<app.P.n&&app.DU.run;i++){const e0=app.epN,k0=app.ok;trainStep();if(app.epN>e0){if(app.ok>k0&&o.first==null)o.first=app.epN;if(app.epN%20===0)o.qh.push(avgMax())}}Math.random=R0;o.ctx=getC()}
export function duDraw(sd){const o=app.DU[sd];setC(o.ctx);drawSim(o.cv);const n=app.epN;o.kp.innerHTML=[["Episode",n+" / "+app.P.n],["Erfolgreich",app.ok],["Fehlgeschlagen",app.fail],["Erfolgsquote",n?Math.round(app.ok/n*100)+"%":"–"],["ε",app.P.eps_.toFixed(3)],["Ø Reward",n?(app.sumRew/n).toFixed(1):"–"],["Bester Fortschritt",Math.round(app.maxIdx/(app.T.p.length-1)*100)+"%"],["Beste Zeit",app.best?(app.best.steps/60).toFixed(2)+" s":"–"]].map(a=>`<div>${a[0]}<b>${a[1]}</b></div>`).join("");
 const x=hd(o.ch);x.clearRect(0,0,320,60);x.strokeStyle="#ff2d3d";x.beginPath();for(let i=0;i<app.hist.length;i+=Math.max(1,Math.floor(app.hist.length/200))){const w=app.hist.slice(Math.max(0,i-49),i+1),v=w.reduce((a,b)=>a+b,0)/w.length,X=i/Math.max(1,app.hist.length-1)*320,Y=56-v*52;i?x.lineTo(X,Y):x.moveTo(X,Y)}x.stroke();
 if(o.det.open&&app.last){o.det.children[1].innerHTML=`Zustand ${app.last.sk} · Sensoren ${app.last.sens.map(v=>v|0).join("/")} · ${ACT[app.last.a]} (${app.last.ex?"Exploration":"Exploitation"}) · Reward ${app.last.r.toFixed(1)} · Q ${app.last.old.toFixed(2)} → ${app.last.nw.toFixed(2)}`;o.det.children[2].innerHTML="<tr><th>Zustand"+ACT.map(a=>"<th>"+a.replace("Stark ","St. ").replace("Leicht ","L. ")).join("")+"</tr>"+app.recent.slice(0,6).map(k=>{const q=getQ(k),m=Math.max(...q);return`<tr><td>${k}`+q.map(v=>`<td class="${v===m&&m!==0?"mx":""}">${v.toFixed(2)}`).join("")+"</tr>"}).join("")}}
export function djTick(){if(!app.DU)return;app.DU.spf=+$("jS").value;if(app.DU.run&&!app.DU.done){duStep("A");duStep("B");if(app.DU.A.ctx.epN>=app.DU.n&&app.DU.B.ctx.epN>=app.DU.n)djFinish()}if(app.DU.run&&!app.DU.done){if(++app.DU.f%3===0){duDraw("A");duDraw("B")}}else{const sg=[app.DU.done,app.DU.A.ctx.epN,app.DU.B.ctx.epN,app.DU.A.det.open,app.DU.B.det.open].join("|"),now=performance.now();if(sg!==app.DU.sig||now-(app.DU.t||0)>1000){app.DU.sig=sg;app.DU.t=now;duDraw("A");duDraw("B")}}} // F6
export function djFinish(){app.DU.partial=app.DU.A.ctx.epN<app.DU.n||app.DU.B.ctx.epN<app.DU.n;app.DU.done=true;app.DU.run=false;djBtns();duDraw("A");duDraw("B");djEval()}
export function djEval(){const f=sd=>{const o=app.DU[sd],x=o.ctx;return{q:x.epN?x.ok/x.epN:0,first:o.first,t:x.best?x.best.steps/60:null,r:x.epN?x.sumRew/x.epN:0,k:x.ok,qm:o.qh.length?o.qh[o.qh.length-1]:0}},a=f("A"),b=f("B");
 const pc=v=>Math.round(v*100)+" %",tm=v=>v==null?"–":v.toFixed(2)+" s",fe=v=>v==null?"kein Erfolg":"Episode "+v,row=(n,x,y)=>`<tr><td style="text-align:left">${n}<td>${x}<td>${y}</tr>`;
 const win=[],cmp=(nm,va,vb,hi)=>{if(va==null&&vb==null)return;if(va==null)win.push(["B",nm]);else if(vb==null)win.push(["A",nm]);else if(va!==vb)win.push([(va>vb)===hi?"A":"B",nm])};
 cmp("einer höheren Erfolgsquote",a.q,b.q,true);cmp("der schnelleren Bestzeit",a.t,b.t,false);cmp("einem höheren durchschnittlichen Reward",a.r,b.r,true);
 const lst=a=>a.length<2?a.join(""):a.slice(0,-1).join(", ")+" und "+a[a.length-1],wa=win.filter(w=>w[0]==="A").map(w=>w[1]),wb=win.filter(w=>w[0]==="B").map(w=>w[1]);
 const fz=wa.length&&wb.length?`KI A war bei ${lst(wa)} besser, KI B bei ${lst(wb)}. Ein eindeutiger Gesamtsieger lässt sich anhand dieser Ergebnisse nicht bestimmen.`:wa.length?`KI A hat in diesem Training besser abgeschnitten: Sie war bei ${lst(wa)} vorn.`:wb.length?`KI B hat in diesem Training besser abgeschnitten: Sie war bei ${lst(wb)} vorn.`:(a.k+b.k?"Beide KIs haben in diesem Training gleich abgeschnitten.":"Keine der beiden KIs hat das Ziel erreicht. Mit mehr Episoden oder anderen Werten könnte sich das ändern.");
 $("jr").innerHTML=`<div class="pan" style="margin-top:12px"><h3 style="margin-top:0">Auswertung: ${app.DU.pr.n}</h3>${app.DU.partial?`<p style="color:#ffb020;font-weight:600">Unvollständiges Duell: vorzeitig beendet (KI A ${app.DU.A.ctx.epN} / KI B ${app.DU.B.ctx.epN} von ${app.DU.n} Episoden).</p>`:""}<table style="font:13px system-ui;width:100%"><tr><th><th>KI A (${app.DU.vals.A})<th>KI B (${app.DU.vals.B})</tr>${row("Erfolgsquote",pc(a.q),pc(b.q))}${row("Episoden bis zum ersten Erfolg",fe(a.first),fe(b.first))}${row("Beste Fahrzeit",tm(a.t),tm(b.t))}${row("Ø Reward",a.r.toFixed(1),b.r.toFixed(1))}${row("Erfolgreiche Fahrten",a.k,b.k)}${row("Ø max. Q-Wert (zuletzt)",a.qm.toFixed(1),b.qm.toFixed(1))}</table><canvas id="jq" width="600" height="110" style="width:100%;max-width:700px;margin-top:8px"></canvas><small style="display:block;color:var(--m)">Q-Wert-Entwicklung (Ø max. Q-Wert der besuchten Zustände): rot = KI A, blau = KI B. Ein höherer Q-Wert bedeutet nicht automatisch eine bessere Fahrleistung.</small><p style="font-size:16px;font-weight:600">${fz}</p><p style="color:#ffb020;font-size:14px;margin-top:-6px">Ein einzelnes Duell ist ein Einzelfall – wiederhole es, um sicher zu sein. ${app.DU.seedMode==="same"?"Beide KIs hatten dieselbe Zufallsbasis; jede Wiederholung startet mit einer neuen.":"Die KIs hatten unterschiedliche Zufallsbasen – ein Teil des Unterschieds kann reiner Zufall sein."}</p><div class="row"><button data-click="bvOpen" ${a.t!=null&&b.t!=null?"":"disabled"}>Beste Fahrten vergleichen</button></div></div>`;
 const x=hd($("jq")),all=[...app.DU.A.qh,...app.DU.B.qh],mx=Math.max(1,...all);[["A","#ff2d3d"],["B","#4da3ff"]].forEach(([sd,col])=>{const h=app.DU[sd].qh;x.strokeStyle=col;x.beginPath();h.forEach((v,i)=>{const X=i/Math.max(1,h.length-1)*600,Y=104-v/mx*98;i?x.lineTo(X,Y):x.moveTo(X,Y)});x.stroke()});$("jr").scrollIntoView()}
export function djExit(){if(!app.DU)return;app.NOTOAST=false;const o=app.DU.snap;setC(o);app.T=o.T;app.mask=o.mask;app.roadC=o.roadC;app.st=o.st;app.LAB=null;app.DU=null;app.BV=null;mdl("bv",0);setPU(app.st==="paused");$("bMore").disabled=app.st!=="done";$("bPause").disabled=!(app.st==="training"||app.st==="paused");$("bBest").disabled=$("bRace").disabled=!app.best;if(document.fullscreenElement)document.exitFullscreen();show("lib")}
// Bestenvergleich der beiden Duell-KIs (nur Wiedergabe gespeicherter Bewegungsdaten)
export function bvOpen(){app.BV={a:app.DU.A.ctx.best,b:app.DU.B.ctx.best,k:0,run:true};$("bvS").textContent="";mdl("bv",1)}
export function bvTick(){if(!app.BV||$("bv").style.display!=="flex")return;if(app.BV.run)app.BV.k++;[["bA","A",app.BV.a],["bB","B",app.BV.b]].forEach(([id,sd,bt])=>{const x=hd($(id));x.drawImage(app.roadC,0,0,500,320);const k=Math.min(app.BV.k,bt.steps-1);x.save();x.scale(.5,.5);drawCar(x,0,bt.rec[k*3],bt.rec[k*3+1],bt.rec[k*3+2],sd==="A"?"#ff2d3d":"#4da3ff",1);x.restore();$(id+"t").textContent=`KI ${sd}: ${(Math.min(app.BV.k,bt.steps)/60).toFixed(2)} s von ${(bt.steps/60).toFixed(2)} s`});
 if(app.BV.k>=Math.max(app.BV.a.steps,app.BV.b.steps)){app.BV.run=false;const ta=app.BV.a.steps/60,tb=app.BV.b.steps/60;$("bvS").textContent=ta===tb?"Beide gespeicherten Fahrten sind gleich schnell.":`Schnellere gespeicherte Fahrt: KI ${ta<tb?"A":"B"} (Unterschied ${Math.abs(ta-tb).toFixed(2)} s).`}}

// Initialisierung – wird von main.js in der Reihenfolge der Originaldatei aufgerufen
export function init(){
$("kk").innerHTML='<div class="drawb" id="kOpen"><svg width="76" height="76" viewBox="0 0 24 24" fill="none" stroke="#ff2d3d" stroke-width="1.6" stroke-linejoin="round"><rect x="2" y="5" width="8.5" height="14" rx="2"/><rect x="13.5" y="5" width="8.5" height="14" rx="2"/><path d="M6.2 15V9M17.8 15V9"/></svg><h3 style="margin:10px 0 4px">KI gegen KI</h3><p style="color:var(--m);margin:0;padding:0 16px">Zwei KIs trainieren gleichzeitig nebeneinander. Nur ein Parameter ist unterschiedlich – wer lernt besser?</p></div>';
$("kOpen").onclick=()=>mdl("ko",1);
$("ks").innerHTML=PRE.map((t,i)=>`<option value="${i}">${t.n}</option>`).join("")+'<option value="lab">S-Kurve (Lernstrecke)</option>';
LPAR.forEach(p=>{const b=document.createElement("button");b.textContent=p.n;b.onclick=()=>{app.KP=p;[...$("kg").children].forEach(x=>x.classList.toggle("sel",x===b));koSet(SUG[p.id])};$("kg").appendChild(b)});
["ka","kb"].forEach(id=>$(id).oninput=()=>$(id+"v").textContent=$(id).value);
$("kSug").onclick=()=>app.KP&&koSet(SUG[app.KP.id]);
$("kGo").onclick=()=>{if(!app.KP){toast("Bitte zuerst einen Parameter wählen.");return}const a=+$("ka").value,b=+$("kb").value;if(a===b){toast("Die beiden Werte müssen unterschiedlich sein.");return}
 const sm=$("kr").value,s0=(Math.random()*2147483647)|0,s1=sm==="same"?s0:(s0^0x5bd1e995)>>>0;app.DU={snap:{...getC(),T:app.T,mask:app.mask,roadC:app.roadC,st:app.st},n:+$("kn").value,pr:app.KP,vals:{A:a,B:b},run:true,done:false,f:0,spf:20,A:{},B:{},seedMode:sm,seeds:{A:s0,B:s1}};app.LAB={duel:1};app.NOTOAST=true;
 const tr=$("ks").value;if(tr==="lab")setTrack("Lernstrecke S-Kurve",80,rs(cat(LCTRL),5));else{const t=PRE[+tr];setTrack(t.n,t.w,rs(cat(t.c),5))}
 ["A","B"].forEach(sd=>{const o=app.DU[sd];o.qh=[];o.first=null;o.rng=mul(app.DU.seeds[sd]);app.Q=new Map();app.P={a:.15,g:.95,e:1,d:.995,n:app.DU.n,rg:100,rc:100,rp:3,ri:.5,rd:.5,eps_:1};app.P[app.KP.k]=app.DU.vals[sd];app.epN=app.ok=app.fail=app.sumRew=app.sumSteps=app.maxIdx=app.okSteps=0;app.hist=[];app.best=null;app.logs=[];app.recent=[];app.last=null;app.sn=[];app.epLog=[];app.fails=[];resetCar();app.S=keyOf(app.c);o.ctx=getC();
  const el=$("j"+sd);el.innerHTML=`<h3 style="margin:0 0 6px">KI ${sd} · ${app.KP.n} = ${app.DU.vals[sd]}</h3><canvas width="1000" height="640" style="width:100%;background:#0f1218;border-radius:8px"></canvas><div class="kp" style="margin-top:6px"></div><canvas width="320" height="60" style="width:100%;margin-top:6px"></canvas><details><summary>Q-Learning analysieren</summary><div style="font-size:12px;margin:6px 0"></div><table></table></details>`;o.cv=el.children[1];o.kp=el.children[2];o.ch=el.children[3];o.det=el.children[4]});
 $("jt").textContent=`Identisch für beide: Strecke ${app.T.name} · ${app.DU.n} Episoden · ${app.DU.seedMode==="same"?"gleiche Zufallsbasis (Nr. "+app.DU.seeds.A+")":"unterschiedliche Zufallsbasis (A "+app.DU.seeds.A+" / B "+app.DU.seeds.B+")"} · übrige Werte α 0,15 · γ 0,95 · ε 1,00 · Abnahme 0,995 · Rewards Ziel 100 / Crash −100 / Fortschritt 3 / Stillstand 0,5 (außer dem untersuchten Parameter)`;
 $("jr").innerHTML="";djBtns();mdl("ko",0);show("dj");fsOn()};
$("jGo").onclick=()=>{if(!app.DU||app.DU.done)return;app.DU.run=!app.DU.run;djBtns()};
$("jRetry").onclick=()=>{djExit();mdl("ko",1)};
$("jBack").onclick=djExit;
$("jEnd").onclick=()=>{if(app.DU&&!app.DU.done)djFinish()};
$("bvP").onclick=()=>{if(app.BV)app.BV.run=!app.BV.run};
$("bvR").onclick=()=>{if(app.BV){app.BV.k=0;app.BV.run=true;$("bvS").textContent=""}};
}
